import org.openenglish.reader.*;import android.content.Context;import java.io.*;
public class JapaneseReadingTest {
 public static void main(String[] args)throws Exception{Context c=new Context(new File(args[0]),new File(args[0]));long at=System.nanoTime();String kana=JapaneseReading.kana(c,"今日はコーヒーを一杯お願いします。");System.out.println("KANA: "+kana+" HOST_WARM_MS="+(System.nanoTime()-at)/1000000);if(!kana.contains("キョー")&&!kana.contains("キョウ"))throw new AssertionError("today reading");if(!kana.contains("コーヒー"))throw new AssertionError("katakana retained");if(!kana.contains("イッパイ"))throw new AssertionError("counter reading");if(!kana.contains("オネガイ"))throw new AssertionError("kanji reading");String help=JapaneseReading.kana(c,"何をお手伝いできますか？");System.out.println("HELP: "+help);if(!help.contains("ナニ")||!help.contains("オテツダイ"))throw new AssertionError("model kanji fallback");System.loadLibrary("english_speech");float[] pcm=IslandSpeech.render(args[1],"ja",help,new LocalNative.Callbacks(){public boolean abort(){return false;}public void text(String s){}public void segment(long a,long b,String s){}});if(!LocalWav.hasSignal(pcm)||pcm.length<16000)throw new AssertionError("kana to real offline speech");LessonAudio.writeSpeech(new File("build/magic-tests/japanese-kanji.wav"),pcm);System.out.println("JAPANESE_READING_CHECKS: 6");}
}
